import React from "react";
import { Line } from "react-chartjs-2";
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from "chart.js";
ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

export default function ChartView({ chartData }){
  if(!chartData) return <div style={{height:200}}>No chart. Ask a query.</div>;

  const price = chartData.price || { labels:[], series:[] };
  const demand = chartData.demand || { labels:[], series:[] };

  const labels = price.labels.length ? price.labels : demand.labels;

  const data = {
    labels,
    datasets: [
      {
        label: "Avg Price",
        data: price.series || [],
        tension: 0.2,
      },
      {
        label: "Demand",
        data: demand.series || [],
        tension: 0.2,
      }
    ]
  };

  return <div style={{height:250}}><Line data={data} /></div>;
}
